import {getLanguage} from './i18n.js';
import {dotAirAsset,dotAirAirports,dotAirLinks,dotAirDna} from './dot-air-content.js';
import './dot-air-motion.js';
import {dotAirReleases} from './dot-air-releases.js';
export const da=(zh,en)=>getLanguage()==='en'?en:zh;
const ic=id=>`<svg class="ic" aria-hidden="true"><use href="./assets/flow/current-icons.svg#${id}"></use></svg>`;
export const flaps=(text,n)=>`<span class="da-flaps" data-flap="${text}" data-flap-size="${n}" aria-hidden="true">${[...text.padEnd(n).slice(0,n)].map(c=>`<i>${c===' '?'&nbsp;':c}</i>`).join('')}</span>`;
const board=()=>`<div class="da-board" data-da-board role="group" aria-label="${da('出发看板','Departure board')}"><div class="da-board-cell"><span>${da('出发','From')}</span>${flaps('DXB',3)}</div><div class="da-board-arc" aria-hidden="true"><i></i></div><div class="da-board-cell"><span>${da('到达','To')}</span>${flaps('DXB',3)}</div><div class="da-board-cell da-board-cell--wide"><span>${da('理论大圆距离','Great-circle distance')}</span>${flaps('ORIGIN',9)}</div><p class="visually-hidden" data-da-board-say aria-live="polite"></p></div>`;
export const dotAirMark='<span class="da-mark" aria-hidden="true"><i></i></span>';
export function dotAirGlobe(interactive=false){return `<div class="da-globe" data-dot-air-globe data-interactive="${interactive}" role="${interactive?'group':'presentation'}"${interactive?` aria-label="${da('交互式波点地球','Interactive dotted Earth')}"`:''}><img class="da-globe-fallback" src="${dotAirAsset}globe.svg" width="700" height="700" alt="" loading="lazy"><canvas${interactive?` tabindex="0" role="img" aria-label="${da('三维波点地球。拖动或方向键旋转','Three-dimensional dotted Earth. Drag or use arrow keys to rotate')}"`:' aria-hidden="true"'}></canvas><span class="da-pin" aria-hidden="true">DXB</span></div>`;}
// Window series A: the Posts cover/hero and the two Now windows share one grammar (see flow-windows-a.css).
const daWindow=({data,title,line})=>`<div class="wa-motif"><span class="wa-dots" aria-hidden="true"></span>${dotAirGlobe()}<p class="wa-board" data-da-cycle aria-hidden="true">${flaps('DXB',3)}<b></b>${flaps('LHR',3)}<em>${flaps('5,479 KM',9)}</em></p></div><div class="wa-type"><p class="wa-data"><span>${dotAirMark}${data[0]}</span><span>${data[1]}</span></p><div class="wa-head"><strong class="wa-title">${title}</strong><span class="wa-line">${line}</span></div></div>`;
export function dotAirPostArt(){return `<div class="wa wa--dotair" aria-hidden="true">${daWindow({data:['DOT/AIR / Departure notes','09 Oct 2026'],title:'Every<br>flight.',line:'Your way. Infinite sky, individual flight.'})}</div>`;}
const daFinsWindow=()=>`<div class="wa wa--dotair wa--dotair-fins"><div class="wa-motif"><span class="wa-dots" aria-hidden="true"></span><span class="da-fin-row" aria-hidden="true">${['EK','BA','SQ'].map((c,i)=>`<img class="da-fin" style="--i:${i}" src="${dotAirAsset+c}.svg" width="155" height="200" alt="" loading="lazy" decoding="async">`).join('')}</span><p class="wa-board" data-da-cycle="airlines" aria-hidden="true">${flaps('CCA',3)}<b></b>${flaps('CA',3)}<em>${flaps('AIR CHINA',9)}</em></p></div><div class="wa-type"><p class="wa-data"><span>${dotAirMark}DOT/AIR 1.2 / Airline Identity</span><span>031</span></p><div class="wa-head"><strong class="wa-title">Every<br>tail.</strong><span class="wa-line">Every tail tells a story.</span></div></div></div>`;
const daWhiteRoomWindow=()=>`<div class="wa wa--dotair wa--whiteroom" data-da-whiteroom><div class="wa-motif" aria-hidden="true"><span class="wr-rules"></span><span class="wr-floor"></span><span class="wr-planet"><i class="wr-dots"></i><i class="wr-gloss"></i></span><span class="wr-wall"></span><span class="wr-sign">白之间<i></i></span></div><div class="wa-type"><p class="wa-data"><span>DOT/AIR 2.0 / The White Room</span><span>032</span></p><div class="wa-head"><strong class="wa-title">The White<br>Room.</strong><span class="wa-line">A red, dotted planet in a white room.</span></div></div></div>`;
export function dotAirNowArt(edition){if(edition==='2.0')return daWhiteRoomWindow();if(edition==='1.2')return daFinsWindow();const update=edition==='1.1';return `<div class="wa wa--dotair">${daWindow(update?{data:['DOT/AIR 1.1 / Orbital Earth','029'],title:'Next<br>orbit.',line:'The same Earth. The next journey.'}:{data:['DOT/AIR / Departure','028'],title:'The world<br>in dots.',line:'Infinite sky.'})}</div>`;}
const releaseCopy=pair=>pair[getLanguage()==='en'?1:0];
const pick=v=>Array.isArray(v)?releaseCopy(v):v;
export function dotAirDnaBoard(){const en=getLanguage()==='en'?1:0;return `<div class="da-dna-board" data-da-dna><p class="da-dna-intro">${da('DOT/AIR 1.1 的入门问卷，在这里排成一条波点基因。点一点，换一种飞法。','The DOT/AIR 1.1 onboarding questions, set as one dotted strand. Tap to fly differently.')}</p><div class="da-genes">${dotAirDna.map((g,gi)=>{const picks=[].concat(g.pick);return `<div class="da-gene" role="${g.multi?'group':'radiogroup'}" aria-label="${g.name[en]}" data-gene="${g.key}"${g.multi?' data-multi':''}><span class="da-gene-name">${g.name[en]}</span><span class="da-gene-dots">${g.options.map((o,oi)=>`<button type="button" class="da-allele" ${g.multi?`aria-pressed="${picks.includes(oi)}"`:`role="radio" aria-checked="${picks.includes(oi)}" tabindex="${picks.includes(oi)?0:-1}"`} data-allele="${oi}" style="--i:${oi};--g:${gi}"><span class="visually-hidden">${o[en]}</span></button>`).join('')}</span><span class="da-gene-value" aria-hidden="true">${g.options.filter((o,oi)=>picks.includes(oi)).map(o=>o[en]).join(' + ')||'—'}</span></div>`;}).join('')}</div><div class="da-dna-strand" aria-hidden="true">${dotAirDna.map((g,gi)=>`<span data-strand="${gi}">${g.options.map(()=>'<i></i>').join('')}</span>`).join('')}</div><p class="da-dna-note">${da('展柜里的交互作品：不会保存，也不会发起推荐或搜索。','An exhibit interaction: nothing is saved, recommended or searched.')}</p></div>`;}
export function dotAirHistory(){return `<details class="da-history" id="dot-air-history" data-dot-air-art><summary><span class="da-history-label">THE EDITION JOURNAL</span><span class="da-history-title">${da('版本手记','THE EDITION LOG')}<small>${da('从第一个点，到白之间里的那颗红色星球。','From the first dot to the red planet in the White Room.')}</small></span><span class="da-history-versions">${dotAirReleases.map(r=>r.label).join(` <i class="da-back">${ic('arrow-right')}</i> `)}</span><b class="da-history-toggle" aria-hidden="true"></b></summary><div class="da-history-body">${dotAirReleases.map((release,index)=>`<article class="da-release${release.current?' da-release--current':''}${release.white?' da-release--white':''}" id="dot-air-release-${release.label.replace('.','-')}"><div class="da-ticket"><div class="da-release-meta"><span>${release.current?da('当前版本','CURRENT EDITION'):index===dotAirReleases.length-1?da('第一版本','FIRST EDITION'):da('历史版本','EARLIER EDITION')}</span><time datetime="${release.date}">${release.date.replaceAll('-','.')}</time></div><div class="da-release-heading"><strong>${release.label}</strong><div><span class="da-overline">${release.edition} / ${String(dotAirReleases.length-index).padStart(2,'0')}</span><h4>${releaseCopy(release.title)}</h4><p>${releaseCopy(release.intro)}</p></div></div><span class="da-ticket-barcode" aria-hidden="true">${[...release.label+release.date].map(c=>`<i style="--h:${(c.charCodeAt(0)%5)+2}"></i>`).join('')}</span></div><div class="da-release-changes">${release.changes.map((change,i)=>`<section><span>0${i+1}</span><h5>${releaseCopy(change.title)}</h5><p>${releaseCopy(change.copy)}</p></section>`).join('')}</div><figure class="da-release-capture"><img src="${pick(release.image)}" width="${release.imageSize[0]}" height="${release.imageSize[1]}" loading="lazy" alt="${releaseCopy(release.imageAlt)}"><figcaption>${releaseCopy(release.caption)} <a class="da-release-original" href="${pick(release.image)}" target="_blank" rel="noopener noreferrer">${da("查看原图","VIEW ORIGINAL")} ${ic('arrow-up-right')}</a></figcaption></figure>${release.secondImage?`<figure class="da-release-capture"><img src="${release.secondImage}" width="${release.secondSize[0]}" height="${release.secondSize[1]}" loading="lazy" alt="${releaseCopy(release.secondAlt)}"><figcaption>${releaseCopy(release.secondCaption)} <a class="da-release-original" href="${release.secondImage}" target="_blank" rel="noopener noreferrer">${da("查看原图","VIEW ORIGINAL")} ${ic('arrow-up-right')}</a></figcaption></figure>`:''}<div class="da-release-end"><p>${releaseCopy(release.note)}</p><a href="${release.href}"${release.href.startsWith('https:')?' target="_blank" rel="noopener noreferrer"':''}>${releaseCopy(release.linkText)} ${ic('arrow-up-right')}</a></div></article>`).join('')}</div></details>`;}
const controls=()=>`<div class="da-console"><div><span class="da-overline">${da('换一个视角','A NEW POINT OF VIEW')}</span><div class="da-airports" aria-label="${da('地球视角','Earth viewpoint')}">${dotAirAirports.map(a=>`<button type="button" data-da-airport="${a.code}" aria-pressed="${a.code==='DXB'}"><b>${a.code}</b><span>${a.name[getLanguage()==='en'?1:0]}</span></button>`).join('')}</div></div>${board()}<div class="da-orbit-controls"><button type="button" data-da-pause aria-pressed="false">${da('暂停地球','PAUSE EARTH')}</button><button type="button" data-da-light aria-pressed="false">${da('夜间灯光','NIGHT LIGHT')}</button></div></div>`;
const roomHeading=()=>'<div class="da-display"><h3><span class="da-line-mask"><span class="da-line">EVERY</span></span><span class="da-line-mask"><span class="da-line">FLIGHT<i></i></span></span></h3><div class="da-way">YOUR <span>WAY.</span></div></div>';
function hero(){return `<div class="da-hero" data-dot-air-art><div class="da-hero-top"><span>THE WHITE ROOM / 2.0</span><span>INFINITE SKY. INDIVIDUAL FLIGHT.</span></div><div class="da-hero-copy">${roomHeading()}<p>${da('无限的点。真实的天空。<br>每一段飞行，都有你的坐标。','Infinite dots. A real sky.<br>A point of departure that belongs to you.')}</p></div>${dotAirGlobe(true)}<div class="da-coordinate" aria-live="polite"><span>YOUR POINT OF VIEW</span><strong data-da-code>DXB</strong><span data-da-coordinates>25.25° N / 55.37° E</span></div></div>${controls()}<div class="da-scene-caption"><span>${da('拖动球体 · 方向键旋转 · 选择机场转向','DRAG TO ROTATE · ARROW KEYS · PICK AN AIRPORT')}</span><span data-da-status role="status">${da('正在载入球面点云，静态地球已就位。','Loading the dot cloud. Static Earth is ready.')}</span></div>`;}
const links=()=>`<div class="da-links"><a href="${dotAirLinks.site}" target="_blank" rel="noopener noreferrer">${da('进入 DOT/AIR','OPEN DOT/AIR')} ${ic('arrow-up-right')}</a><a href="${dotAirLinks.post}">${da('出发手记','DEPARTURE NOTE')} ${ic('arrow-up-right')}</a><a href="${dotAirLinks.now}">${da('这次的 Now','THE NOW ENTRY')} ${ic('arrow-up-right')}</a></div>`;
const plate=()=>`<figure class="da-plate"><div class="da-plate-frame"><img src="${dotAirAsset}${da('white-room-2.0-zh.webp','white-room-2.0-en.webp')}" width="1600" height="1000" alt="${da('已上线 DOT/AIR 2.0 白之间的 Web 真实界面','Actual published DOT/AIR 2.0 Web interface in the White Room')}" loading="lazy"></div><figcaption>${da('真实正式 Web 界面 / DOT/AIR 2.0','ACTUAL PUBLISHED WEB INTERFACE / DOT/AIR 2.0')}</figcaption></figure>`;
export function dotAirCard(){return `<article class="exhibit da-exhibit da-room" id="project-dot-air" data-da-exhibit data-theme="dark"><header class="da-masthead"><h2>${dotAirMark}DOT/AIR<sup>®</sup></h2><span>09 / A PERSONAL FLIGHT ATLAS</span><button type="button" data-project="dot-air">${da('软件与制作档案','THE SOFTWARE FOLIO')} ${ic('arrow-up-right')}</button></header>${hero()}${plate()}<section class="da-atlas"><div class="da-section-heading"><span class="da-overline">02 / FLEET ATLAS</span><h3>${da('一眼，<br>认出你的天空。','A SKY YOU<br>RECOGNISE.')}</h3><p>${da('公共航空资料、机队与机身参考。<br>每一个坐标，都有清楚的来处。','Public aviation, fleet and aircraft references.<br>Every coordinate keeps its source.')}</p></div><div class="da-tail-gallery">${[['EK','Emirates','UAE'],['BA','British Airways','BAW'],['SQ','Singapore Airlines','SIA']].map(([code,name,icao],i)=>`<a class="da-tail da-tail-${i}" href="${dotAirLinks.site}/fleet" target="_blank" rel="noopener noreferrer"><span class="da-overline">0${i+1} / ${icao}</span><div class="da-tail-disc"></div><img src="${dotAirAsset+code}.svg" width="155" height="200" loading="lazy" alt="${name} ${da('垂尾插画','tail illustration')}"><strong>${name}</strong><span>FLEET ATLAS ${ic('arrow-up-right')}</span></a>`).join('')}</div></section><section class="da-dna" data-da-dna-section><div class="da-dna-copy"><span class="da-overline">03 / FLIGHT DNA</span><h3>${da('你的偏好。<br>你的飞行规则。','YOUR PREFERENCES.<br>YOUR FLIGHT RULES.')}</h3><p>${da('预算、时间、航空兴趣。<br>推荐可以有理由，最后的选择属于你。','Budget, time, aviation interests.<br>A recommendation has reasons. The choice is yours.')}</p><a href="${dotAirLinks.site}/algorithm" target="_blank" rel="noopener noreferrer">${da('了解 Flight DNA','EXPLORE FLIGHT DNA')} ${ic('arrow-up-right')}</a></div>${dotAirDnaBoard()}</section>${dotAirHistory()}<footer class="da-folio"><div><span class="da-overline">WEB + NATIVE WINDOWS / 2.0.0</span><p>${da('同一套账户与偏好，两种看天空的方式。','One account and preferences. Two ways to explore the sky.')}</p></div>${links()}<p class="da-note">${da('公共资料版：可售航班与票价尚未接入供应商，不提供预订或出票。机队、照片与涂装均为带来源和日期的参考。','Public-data edition: live flight inventory and fares await a provider; no booking or ticketing. Fleet, photograph and livery records remain dated references.')}</p><p class="da-credit">${da('地球：DOT/AIR 原始点云 / 地理数据','Earth: original DOT/AIR dot cloud / geography')} <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">Natural Earth</a> · ${da('航司垂尾','Airline tails')} <a href="https://github.com/AlaskaAirlines/Icons" target="_blank" rel="noopener noreferrer">Auro / Apache 2.0</a></p></footer></article>`;}
export function dotAirDetail(){return `<section class="da-detail" data-da-exhibit><header class="da-detail-head"><span class="da-overline">PROJECT 09 / THE WHITE ROOM 2.0</span><h2 id="dialog-title">${dotAirMark}DOT/AIR</h2><p>${da('每一个点，都可以是出发点。','Every dot, a departure.')}</p></header><figure class="da-software"><img src="${dotAirAsset}${da('white-room-2.0-zh.webp','white-room-2.0-en.webp')}" width="1600" height="1000" alt="${da('已上线 DOT/AIR 2.0 白之间的 Web 真实界面','Actual published DOT/AIR 2.0 Web interface in the White Room')}" loading="lazy"><figcaption>${da('真实正式 Web 界面 / DOT/AIR 2.0','ACTUAL PUBLISHED WEB INTERFACE / DOT/AIR 2.0')}</figcaption></figure><figure class="da-software da-software--past"><img src="${dotAirAsset}software-v1.1.png" width="1265" height="712" alt="${da('DOT/AIR 1.1 Web 真实界面，未登录的公开视图','DOT/AIR 1.1 Web interface, signed-out public view')}" loading="lazy"><figcaption>${da('上一版正式 Web 界面 / DOT/AIR 1.1','PREVIOUS PUBLISHED WEB INTERFACE / DOT/AIR 1.1')}</figcaption></figure><div class="da-detail-body"><h3>${da('一颗球，连接一整个航空兴趣。','ONE EARTH. A WORLD OF AVIATION CURIOSITY.')}</h3><p>${da('机场探索、公共空域、注册号与机队图鉴、偏好、收藏和飞行日志。原生 Windows WPF 工作台以固定导航、局部滚动列表和机身检查器展开；Web 与桌面端共用版本化 API、账户与偏好。','Airport discovery, public airspace, registration and fleet references, preferences, collections and a flight journal. A native Windows WPF workspace uses persistent navigation, scrolling lists and an aircraft inspector. Web and desktop share a versioned API, account and preferences.')}</p>${links()}<p class="da-note">${da('DOT/AIR 2.0 已上线；Web 与原生 Windows 一起换成白之间。可售航班、票价和出票尚不可用。这里的球面交互是一件作品展示，不会发起真实航班搜索。','DOT/AIR 2.0 is live; Web and native Windows move into the White Room together. Purchasable flights, fares and ticketing remain unavailable. This exhibit’s sphere is an artwork interaction and does not perform a live flight search.')}</p></div></section>`;}
